#!/usr/bin/env python3

# This script is used to generate the binary files for song appending
#
# The goal is to convert the "memory locations" generated by mmutil in soundbank.h
# into a binary file that the game can read during runtime.

import os, sys, struct, time

directory = 'audio'

build_type = "default"

try:
    build_type = sys.argv[1]
except:
    pass

mmutil_header = "tools/soundbank.h"             # header generated by mmutil containing asset "memory locations"
soundbank_binary = "tools/soundbank.bin"        # soundbank binary generated by mmutil containing sound effects (which gets appended onto the ROM afterwards)
defaults_header = "tools/audio_files.h"         # default songs and sound effect definitions used in the game's code
location_binary = "tools/effect_locations.bin"  # binary containing the "memory locations" extracted from the mmutil header

if(build_type == "default"):
    mmutil_header = "tools/soundbank.h"
    soundbank_binary = "data/soundbank.bin"
    defaults_header = "include/audio_files.h"
    location_binary = "data/effect_locations.bin"

# build mmutil input argument
count = 0
music_count = 0
files = ""

for filename in os.listdir(directory):
    if(filename.find('.wav') != -1):
        files += f"{directory}/{filename} "

        count+=1

    if(filename.find('.mod') != -1) or (filename.find('.it') != -1) or (filename.find('.xm') != -1):
        files += f"{directory}/{filename} "

        music_count+=1

# run mmutil
os.system(f"mmutil {files} -o{soundbank_binary} -h{mmutil_header} > /dev/null")

# wait for mmutil to finish
print("Waiting for header...")
tries = 0
while tries < 100:
    if os.path.exists(mmutil_header):
        break

    time.sleep(0.1)

    tries += 1
else:
    print("Timed out waiting for header.")
    sys.exit()

# place the generated "memory locations" from soundbank.h into dictionaries

effect_list = {}
song_list = {}

with open(mmutil_header) as f:
    for line in f:
        line = line.split()[1:]#split into words and ditch #define

        if(line[0].find('MSL') != -1):
            continue

        if(line[0].find('SFX') != -1):
            effect_list[line[0]] = int(line[1])

        elif(line[0].find('MOD') != -1):
            song_list[line[0]] = int(line[1])

print("\nsfx locations: ")
print(effect_list)
print("\nsong locations: ")
print(song_list)

# create lists containing the "memory locations" for the default assets in audio_files.h

sfx = []
songs = []

preset_songs = [] #keep track of default song names for later

song_count = 0

with open(defaults_header) as f:
    for line in f:
        if (line.find("SFX") != -1 and line[0] == '\t'):
            line = line.replace("\t","")
            line = line.replace(",","")
            line = line.replace("\n","")

            try:
                sfx.append(effect_list[line])
            except:
                sfx.append(-1)

        if (line.find("MOD") != -1 and line[0] == '\t'):
            line = line.replace("\t","")
            line = line.replace(",","")
            line = line.replace("\n","")

            preset_songs.append(line)
            try:
                songs.append(song_list[line])
                song_count+=1
            except:
                songs.append(-1)

print("\ndefaults:")
print(sfx)
print(songs)
print(preset_songs)

# finally, create the output location_binary file

with open(location_binary,"wb") as result:
    def write(num):
        result.write(struct.pack('<i',int(num)))

    write(81) # save tag, exists validate binary

    # sfx count and locations
    write(len(sfx))
    for s in sfx:
        write(s)

    write(len(songs))
    write(len(song_list) - song_count)

    # write default songs
    for s in songs:
        write(s)

    # write non-default songs
    for key in song_list:
        if key in preset_songs:
            continue

        write(song_list[key])
